pleto":"Comuna Buena Vista","categoria":"Comuna","nombre_final":"Buena Vista"},{"codigo":"908504","provincia":"90","nombre":"Ciudacita","nombre_completo":"Comuna Ciudacita","categoria":"Comuna","nombre_final":"Ciudacita"},{"codigo":"908511","provincia":"90","nombre":"Manuela Pedraza","nombre_completo":"Comuna Manuela Pedraza","categoria":"Comuna","nombre_final":"Manuela Pedraza"},{"codigo":"908518","provincia":"90","nombre":"Monteagudo","nombre_completo":"Comuna Monteagudo","categoria":"Comuna","nombre_final":"Monteagudo"},{"codigo":"908525","provincia":"90","nombre":"Pampa Mayo","nombre_completo":"Comuna Pampa Mayo","categoria":"Comuna","nombre_final":"Pampa Mayo"},{"codigo":"908532","provincia":"90","nombre":"Río Chico y Nueva Trinidad","nombre_completo":"Comuna Río Chico y Nueva Trinidad","categoria":"Comuna","nombre_final":"Río Chico y Nueva Trinidad"},{"codigo":"908539","provincia":"90","nombre":"San Pedro y San Antonio","nombre_completo":"Comuna San Pedro y San Antonio","categoria":"Comuna","nombre_final":"San Pedro y San Antonio"},{"codigo":"908546","provincia":"90","nombre":"Santa Cruz y La Tuna","nombre_completo":"Comuna Santa Cruz y La Tuna","categoria":"Comuna","nombre_final":"Santa Cruz y La Tuna"},{"codigo":"908553","provincia":"90","nombre":"Villa Chicligasta","nombre_completo":"Comuna Villa Chicligasta","categoria":"Comuna","nombre_final":"Villa Chicligasta"},{"codigo":"908560","provincia":"90","nombre":"Yerba Buena","nombre_completo":"Comuna Yerba Buena","categoria":"Comuna","nombre_final":"Comuna Yerba Buena"},{"codigo":"908567","provincia":"90","nombre":"Amaicha del Valle","nombre_completo":"Comuna Amaicha del Valle","categoria":"Comuna","nombre_final":"Amaicha del Valle"},{"codigo":"908574","provincia":"90","nombre":"Colalao del Valle","nombre_completo":"Comuna Colalao del Valle","categoria":"Comuna","nombre_final":"Colalao del Valle"},{"codigo":"908581","provincia":"90","nombre":"El Mollar","nombre_completo":"Comuna El Mollar","categoria":"Comuna","nombre_final":"El Mollar"},{"codigo":"908588","provincia":"90","nombre":"Raco","nombre_completo":"Comuna Raco","categoria":"Comuna","nombre_final":"Raco"},{"codigo":"908595","provincia":"90","nombre":"Anca Juli","nombre_completo":"Comuna Anca Juli","categoria":"Comuna","nombre_final":"Anca Juli"},{"codigo":"908602","provincia":"90","nombre":"El Cadillal","nombre_completo":"Comuna El Cadillal","categoria":"Comuna","nombre_final":"El Cadillal"},{"codigo":"908609","provincia":"90","nombre":"La Esperanza","nombre_completo":"Comuna La Esperanza","categoria":"Comuna","nombre_final":"La Esperanza"},{"codigo":"908616","provincia":"90","nombre":"Los Nogales","nombre_completo":"Comuna Los Nogales","categoria":"Comuna","nombre_final":"Los Nogales"},{"codigo":"908623","provincia":"90","nombre":"Choromoro","nombre_completo":"Comuna Choromoro","categoria":"Comuna","nombre_final":"Choromoro"},{"codigo":"908630","provincia":"90","nombre":"San Pedro de Colalao","nombre_completo":"Comuna San Pedro de Colalao","categoria":"Comuna","nombre_final":"San Pedro de Colalao"},{"codigo":"908637","provincia":"90","nombre":"Tapia","nombre_completo":"Comuna Tapia","categoria":"Comuna","nombre_final":"Tapia"},{"codigo":"908644","provincia":"90","nombre":"Cevil Redondo","nombre_completo":"Comuna Cevil Redondo","categoria":"Comuna","nombre_final":"Cevil Redondo"},{"codigo":"908651","provincia":"90","nombre":"San Javier","nombre_completo":"Comuna San Javier","categoria":"Comuna","nombre_final":"San Javier"},{"codigo":"940007","provincia":"94","nombre":"Río Grande","nombre_completo":"Municipio Río Grande","categoria":"Municipio","nombre_final":"Río Grande"},{"codigo":"940014","provincia":"94","nombre":"Ushuaia","nombre_completo":"Municipio Ushuaia","categoria":"Municipio","nombre_final":"Ushuaia"},{"codigo":"940021","provincia":"94","nombre":"Tolhuin","nombre_completo":"Municipio Tolhuin","categoria":"Municipio","nombre_final":"Tolhuin"}]$j$;
  v_alias_prov jsonb := $j$[{"nombre":"Tierra del Fuego","codigo":"94"}]$j$;
  v_alias_part jsonb := $j$[{"nombre":"Mar del Plata (General Pueyrredón)","codigo":"060357"},{"nombre":"Gualeguaychú","codigo":"300189"}]$j$;
  v_n integer;
  v_lista text;
BEGIN
  -- 1. Provincias: por nombre normalizado y, si no, por alias.
  UPDATE provincias p SET codigo_georef = x.codigo
    FROM jsonb_to_recordset(v_prov) AS x(codigo text, nombre text)
   WHERE p.codigo_pais = 'AR' AND p.codigo_georef IS NULL
     AND regexp_replace(lower(translate(btrim(p.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') = regexp_replace(lower(translate(btrim(x.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')
     AND NOT EXISTS (SELECT 1 FROM provincias o WHERE o.codigo_georef = x.codigo);
  UPDATE provincias p SET codigo_georef = a.codigo
    FROM jsonb_to_recordset(v_alias_prov) AS a(nombre text, codigo text)
   WHERE p.codigo_pais = 'AR' AND p.codigo_georef IS NULL
     AND regexp_replace(lower(translate(btrim(p.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') = regexp_replace(lower(translate(btrim(a.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')
     AND NOT EXISTS (SELECT 1 FROM provincias o WHERE o.codigo_georef = a.codigo);
  SELECT string_agg(x.nombre, ', ') INTO v_lista
    FROM jsonb_to_recordset(v_prov) AS x(codigo text, nombre text)
   WHERE NOT EXISTS (SELECT 1 FROM provincias p WHERE p.codigo_georef = x.codigo);
  IF v_lista IS NOT NULL THEN
    RAISE EXCEPTION 'Provincias de Georef sin fila en provincias: %', v_lista;
  END IF;

  -- 2. Partidos existentes por (provincia, nombre normalizado), solo si el nombre es único de los
  --    dos lados.
  WITH g AS (
    SELECT x.*, pr.id_provincia, regexp_replace(lower(translate(btrim(x.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') AS n,
           count(*) OVER (PARTITION BY x.provincia, regexp_replace(lower(translate(btrim(x.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')) AS rep
      FROM jsonb_to_recordset(v_gl) AS x(codigo text, provincia text, nombre text, nombre_completo text,
                                         categoria text, nombre_final text)
      JOIN provincias pr ON pr.codigo_georef = x.provincia
  ), viejos AS (
    SELECT pa.id_partido, pa.id_provincia, regexp_replace(lower(translate(btrim(pa.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') AS n,
           count(*) OVER (PARTITION BY pa.id_provincia, regexp_replace(lower(translate(btrim(pa.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')) AS rep
      FROM partidos pa WHERE pa.codigo_georef IS NULL
  )
  UPDATE partidos pa SET codigo_georef = g.codigo, categoria = g.categoria, nombre_completo = g.nombre_completo
    FROM viejos v JOIN g ON g.id_provincia = v.id_provincia AND g.n = v.n
   WHERE pa.id_partido = v.id_partido AND v.rep = 1 AND g.rep = 1
     AND NOT EXISTS (SELECT 1 FROM partidos o WHERE o.codigo_georef = g.codigo);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'casados por nombre: %', v_n;

  -- 3. Alias: el mismo lugar con otro nombre (nombre viejo → código), dentro de la provincia del código.
  WITH g AS (
    SELECT x.codigo, x.categoria, x.nombre_completo, pr.id_provincia
      FROM jsonb_to_recordset(v_gl) AS x(codigo text, provincia text, nombre text, nombre_completo text,
                                         categoria text, nombre_final text)
      JOIN provincias pr ON pr.codigo_georef = x.provincia
  )
  UPDATE partidos pa SET codigo_georef = g.codigo, categoria = g.categoria, nombre_completo = g.nombre_completo
    FROM jsonb_to_recordset(v_alias_part) AS a(nombre text, codigo text) JOIN g ON g.codigo = a.codigo
   WHERE pa.codigo_georef IS NULL AND pa.id_provincia = g.id_provincia
     AND regexp_replace(lower(translate(btrim(pa.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') = regexp_replace(lower(translate(btrim(a.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')
     AND NOT EXISTS (SELECT 1 FROM partidos o WHERE o.codigo_georef = g.codigo);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'casados por alias: %', v_n;

  -- 4. Datos oficiales al día en las filas que ya tienen código (re-aplicar actualiza).
  UPDATE partidos pa SET categoria = x.categoria, nombre_completo = x.nombre_completo
    FROM jsonb_to_recordset(v_gl) AS x(codigo text, provincia text, nombre text, nombre_completo text,
                                       categoria text, nombre_final text)
   WHERE pa.codigo_georef = x.codigo
     AND (pa.categoria IS DISTINCT FROM x.categoria OR pa.nombre_completo IS DISTINCT FROM x.nombre_completo);

  -- 5. Alta del resto. Antes, ningún nombre nuevo puede chocar con uno que ya está en la provincia.
  SELECT string_agg(x.nombre_final || ' (' || x.codigo || ')', ', ') INTO v_lista
    FROM jsonb_to_recordset(v_gl) AS x(codigo text, provincia text, nombre text, nombre_completo text,
                                       categoria text, nombre_final text)
    JOIN provincias pr ON pr.codigo_georef = x.provincia
   WHERE NOT EXISTS (SELECT 1 FROM partidos o WHERE o.codigo_georef = x.codigo)
     AND EXISTS (SELECT 1 FROM partidos o WHERE o.id_provincia = pr.id_provincia AND o.nombre = x.nombre_final);
  IF v_lista IS NOT NULL THEN
    RAISE EXCEPTION 'Nombres nuevos que chocan con una fila existente (agregar alias): %', v_lista;
  END IF;
  INSERT INTO partidos (id_provincia, nombre, codigo_georef, categoria, nombre_completo, activo)
  SELECT pr.id_provincia, x.nombre_final, x.codigo, x.categoria, x.nombre_completo, TRUE
    FROM jsonb_to_recordset(v_gl) AS x(codigo text, provincia text, nombre text, nombre_completo text,
                                       categoria text, nombre_final text)
    JOIN provincias pr ON pr.codigo_georef = x.provincia
   WHERE NOT EXISTS (SELECT 1 FROM partidos o WHERE o.codigo_georef = x.codigo);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'gobiernos locales nuevos: %', v_n;

  -- 6. Localidades de filas sin código: a la fila del alias (si el alias apunta a un código que ya
  --    tenía otra fila) o al único gobierno local de la provincia con el mismo nombre que la localidad.
  WITH destino AS (
    SELECT l.id_localidad, d.id_partido AS id_nuevo
      FROM localidades l
      JOIN partidos v ON v.id_partido = l.id_partido AND v.codigo_georef IS NULL
      JOIN jsonb_to_recordset(v_alias_part) AS a(nombre text, codigo text)
        ON regexp_replace(lower(translate(btrim(v.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') = regexp_replace(lower(translate(btrim(a.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')
      JOIN partidos d ON d.codigo_georef = a.codigo AND d.id_provincia = v.id_provincia
  )
  UPDATE localidades l SET id_partido = d.id_nuevo FROM destino d WHERE l.id_localidad = d.id_localidad;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'localidades reubicadas por alias: %', v_n;
  WITH candidatos AS (
    SELECT l.id_localidad, d.id_partido AS id_nuevo,
           count(*) OVER (PARTITION BY l.id_localidad) AS rep
      FROM localidades l
      JOIN partidos v ON v.id_partido = l.id_partido AND v.codigo_georef IS NULL
      JOIN partidos d ON d.id_provincia = v.id_provincia AND d.codigo_georef IS NOT NULL
                     AND regexp_replace(lower(translate(btrim(d.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g') = regexp_replace(lower(translate(btrim(l.nombre), 'ÁÉÍÓÚÜÑáéíóúüñÀÈÌÒÙàèìòùÂÊÎÔÛâêîôûÇç', 'AEIOUUNaeiouunAEIOUaeiouAEIOUaeiouCc')), '\s+', ' ', 'g')
  )
  UPDATE localidades l SET id_partido = c.id_nuevo FROM candidatos c
   WHERE l.id_localidad = c.id_localidad AND c.rep = 1;
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'localidades reubicadas por nombre: %', v_n;

  -- 7. Baja lógica de las filas sin código, salvo las que use un municipio vigente y las de una
  --    provincia de la que Georef no lista ningún gobierno local (Santa Cruz y Santiago del Estero en
  --    2026-10): ahí la fila vieja es lo único que hay para elegir.
  UPDATE partidos pa SET activo = FALSE
   WHERE pa.codigo_georef IS NULL AND pa.activo
     AND NOT EXISTS (SELECT 1 FROM municipios m WHERE m.id_partido = pa.id_partido AND m.estado <> 'baja')
     AND EXISTS (SELECT 1 FROM partidos o WHERE o.id_provincia = pa.id_provincia AND o.codigo_georef IS NOT NULL);
  GET DIAGNOSTICS v_n = ROW_COUNT;
  RAISE NOTICE 'filas viejas dadas de baja: %', v_n;
  SELECT string_agg(pa.nombre, ', ') INTO v_lista FROM partidos pa
   WHERE pa.codigo_georef IS NULL AND pa.activo;
  IF v_lista IS NOT NULL THEN
    RAISE NOTICE 'sin código y activas (municipio vigente o provincia sin datos en Georef): %', v_lista;
  END IF;
  SELECT count(*) INTO v_n FROM localidades l JOIN partidos pa ON pa.id_partido = l.id_partido
   WHERE NOT pa.activo;
  RAISE NOTICE 'localidades que quedaron en filas de baja: %', v_n;
END
$mig$;
